```cpp
#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1000000007LL;

long long modpow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    if (!(cin >> n >> k)) return 0;

    vector<vector<int>> g(n + 1);
    for (int i = 0; i < n - 1; ++i) {
        int u, v; cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }

    if (n % 2 == 1) { // 总点数为奇数，无解
        cout << 0 << '\n';
        return 0;
    }

    // 迭代 DFS：求父亲与访问顺序
    vector<int> parent(n + 1, 0), order;
    order.reserve(n);
    vector<int> st; st.reserve(n);
    st.push_back(1);
    parent[1] = -1;
    while (!st.empty()) {
        int u = st.back(); st.pop_back();
        order.push_back(u);
        for (int v : g[u]) {
            if (v == parent[u]) continue;
            parent[v] = u;
            st.push_back(v);
        }
    }

    // 逆序累加子树大小
    vector<int> sz(n + 1, 1);
    for (int i = (int)order.size() - 1; i >= 0; --i) {
        int u = order[i];
        int p = parent[u];
        if (p != -1) sz[p] += sz[u];
    }

    // 统计偶子树边数 m
    int m = 0;
    for (int v = 2; v <= n; ++v) if (sz[v] % 2 == 0) ++m;

    if (k > m) { cout << 0 << '\n'; return 0; }

    // 组合数 C(m, k) —— 预处理到 n
    vector<long long> fac(n + 1), ifac(n + 1);
    fac[0] = 1;
    for (int i = 1; i <= n; ++i) fac[i] = fac[i - 1] * i % MOD;
    ifac[n] = modpow(fac[n], MOD - 2);
    for (int i = n - 1; i >= 0; --i) ifac[i] = ifac[i + 1] * (i + 1) % MOD;

    auto C = [&](int N, int K)->long long{
        if (K < 0 || K > N) return 0;
        return fac[N] * ifac[K] % MOD * ifac[N - K] % MOD;
    };

    cout << C(m, k) << '\n';
    return 0;
}
